def parse_bool_env(value):
    truthy = {"1", "true", "yes", "on"}
    falsy = {"0", "false", "no", "off"}
    v = value.strip().lower()
    if v in truthy:
        return True
    if v in falsy:
        return False
    raise ValueError(f"не удалось разобрать булево значение: {value!r}")
